/**
 * Schema for the design_agent tool — multi-step LLM-powered design execution.
 */
export const designAgentSchema = {
    name: 'design_agent',
    description: `Describe a complex design task, and an LLM autonomously plans and executes it in multiple steps.

Use this for tasks that require multiple related operations (e.g., building a full page, a multi-component layout, or a design system section). The tool:
1. Plans the task into sequential steps via LLM
2. For each step: generates code, executes it, captures context
3. Each step builds on the results of previous steps
4. On error: retries once, stops on double failure

For simple single-step operations, use smart_execute instead.

Requires \`claude\` or \`codex\` CLI installed and available on PATH.

## Examples
- "Create a login page with email input, password input, and submit button"
- "Build a dashboard header with logo, navigation links, and user avatar"
- "Create a pricing table with 3 tiers: Basic, Pro, and Enterprise"`,
    inputSchema: {
        type: 'object',
        properties: {
            description: {
                type: 'string',
                description: 'Natural language description of the multi-step design task.',
            },
        },
        required: ['description'],
    },
};
